// PuzzleInvalidReason is why a puzzle request was refused as invalid.
type PuzzleInvalidReason int32

const (
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_UNSPECIFIED PuzzleInvalidReason = 0
	// The name is empty or longer than 80 characters.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_NAME PuzzleInvalidReason = 1
	// The clue or a hint is too long or empty, or there are more than 10 hints.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_TEXT PuzzleInvalidReason = 2
	// The kind is missing, or the config, solution, start or move is not of the same kind.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_KIND PuzzleInvalidReason = 3
	// The board, the wheels or the pillars are out of their range.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_SIZE PuzzleInvalidReason = 4
	// A symbol or position is out of range, or a list has the wrong length.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_SYMBOLS PuzzleInvalidReason = 5
	// A pillar's links are not valid.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_LINKS PuzzleInvalidReason = 6
	// The lock's start is already its solution.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_START_SOLVED PuzzleInvalidReason = 7
	// The pillars' mural cannot be reached from where they start.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_UNSOLVABLE PuzzleInvalidReason = 8
	// "Ao resolver" has no target when it needs one, or one it does not use, or the
	// target is not of this campaign.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_TARGET PuzzleInvalidReason = 9
	// The move is not valid for this puzzle (a cell or a wheel that is not there, a turn
	// that is not +1 or -1).
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_MOVE PuzzleInvalidReason = 10
	// The riddle's answers are not valid: none, more than 10, empty, too long, or the same
	// twice.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_ANSWERS PuzzleInvalidReason = 11
	// The cipher's message or key is not valid, or the key clue is not a clue of the
	// campaign.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_CIPHER PuzzleInvalidReason = 12
	// The hint check's skill is not one of the 18, or its DC is out of 1 to 30.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_HINT_CHECK PuzzleInvalidReason = 13
	// The split information's parts are not valid: too many, empty or long text, or a
	// character that is not a living player character of the campaign.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_PARTS PuzzleInvalidReason = 14
	// "Ao errar" is not valid: a limit out of range, a trap that is not a trap point of
	// the campaign, or a trap or attempts on a kind that judges no moves.
	PuzzleInvalidReason_PUZZLE_INVALID_REASON_ON_WRONG PuzzleInvalidReason = 15
)

